107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
115	    }
116	
117	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning} flag the same way
118	     *  for every owner response. */
119	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
122	        return ownerDto;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
128	        // A create retried with an already-seen idempotency key returns the originally created
129	        // owner with 200, rather than creating a duplicate.
130	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
131	        if (existingId != null) {
132	            Owner existing = this.clinicService.findOwnerById(existingId);
133	            if (existing != null) {
134	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
135	            }
136	        }
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        AddressValidator.validate(owner.getAddress());
140	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
141	        DisposableEmailValidator.validate(owner.getEmail());
142	        RegistrationDateValidator.validate(owner.getRegistrationDate());
143	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
144	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
145	        }
146	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
147	        // and postcode are automatically the same household. It no longer gates duplicate detection
148	        // (that is the identity key alone) but still drives household-derived fields.
149	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
150	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
151	        // Duplicate detection is the single identity key: reject only when the new owner's whole
152	        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
153	        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
154	        // telephones have distinct keys and are created as a soft match rather than rejected.
155	        if (this.clinicService.isIdentityKeyInUse(owner)) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
159	            return new ResponseEntity<>(HttpStatus.CONFLICT);
160	        }
161	        this.clinicService.saveOwner(owner, sharesHousehold);
162	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
163	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
164	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
165	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
166	        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
167	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
