173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
181	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
182	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
183	        AddressValidator.validate(currentOwner.getAddress());
184	        currentOwner.setCity(ownerFieldsDto.getCity());
185	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
186	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
187	        currentOwner.setLastName(ownerFieldsDto.getLastName());
188	        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
189	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
190	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Transactional
197	    @Override
198	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner == null) {
201	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	        }
203	        this.clinicService.deleteOwner(owner);
204	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	    }
