226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner != null) {
231	            Pet currentPet = this.clinicService.findPetById(petId);
232	            if (currentPet != null) {
233	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
234	                currentPet.setName(petFieldsDto.getName());
235	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
236	                this.clinicService.savePet(currentPet);
237	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
246	        HttpHeaders headers = new HttpHeaders();
247	        Visit visit = visitMapper.toVisit(visitFieldsDto);
248	        Pet pet = new Pet();
249	        pet.setId(petId);
250	        visit.setPet(pet);
251	        this.clinicService.saveVisit(visit);
252	        VisitDto visitDto = visitMapper.toVisitDto(visit);
253	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
254	            .buildAndExpand(visit.getId()).toUri());
255	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
256	    }
257	
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
